<?php
// Получаем текущий язык через Polylang
$current_lang = function_exists('pll_current_language') ? pll_current_language() : 'en';

$map_query_args = [
    'post_type'      => 'interactive_map',
    'posts_per_page' => -1,
    'post_status'    => 'publish',
    'lang'           => $current_lang,
];

// Используем другую переменную вместо $map_objects для чистоты
$map_posts = get_posts($map_query_args); 
$all_entries = []; 

// КРИТИЧНО: Используем $map_item вместо $post, чтобы не перебивать глобальную переменную
foreach ($map_posts as $map_item) {

    // Регионы
    $region_terms = get_the_terms($map_item->ID, 'map_region') ?: [];
    $regions = array_map(fn($r) => $r->slug, (is_array($region_terms) ? $region_terms : []));

    // Категории
    $cat_terms = get_the_terms($map_item->ID, 'map_category') ?: [];
    $categories = array_map(fn($c) => [
        'slug' => $c->slug, 
        'name' => function_exists('pll__') ? pll__($c->name) : $c->name 
    ], (is_array($cat_terms) ? $cat_terms : []));

    // Данные ACF (используем ID нашего $map_item)
    $img_data = get_field('img_map', $map_item->ID);
    $img_url  = $img_data['url'] ?? $img_data;
    
    $post_text = get_field('text_map', $map_item->ID);
    $btn_text  = get_field('button_text_map', $map_item->ID);
    $btn_link  = get_field('button_link_map', $map_item->ID);

    ob_start(); ?>
    <div class="map-post-card" id="map-post-<?= $map_item->ID ?>">
        <?php if ($img_url): ?>
            <img src="<?= esc_url($img_url) ?>" alt="<?= esc_attr($map_item->post_title) ?>" class="map-post-image">
        <?php endif; ?>

        <h3 class="map-post-title"><?= esc_html($map_item->post_title) ?></h3>
        
        <div class="map-post-text"><?= wpautop(wp_kses_post($post_text)) ?></div>

        <?php if ($btn_text && $btn_link): ?>
            <a href="<?= esc_url($btn_link) ?>" class="map-post-btn">
                <?= esc_html($btn_text) ?>
            </a>
        <?php endif; ?>
    </div>
    <?php
    $post_html = ob_get_clean();

    $all_entries[] = [
        'id'         => $map_item->ID,
        'regions'    => $regions,
        'categories' => $categories,
        'html'       => $post_html,
    ];
}

// КРИТИЧНО: Сбрасываем данные постов, чтобы вернуться к контексту основной страницы
wp_reset_postdata();
?>

<script>
    /**
     * Используем window.mapData, чтобы избежать ошибки SyntaxError.
     * Теперь переменную можно переобъявлять без "Identifier already declared".
     */
  // JSON внутри <script> экранируем, чтобы спец. последовательности не ломали HTML.
  let arr = window.mapData = <?= wp_json_encode(
  	$all_entries,
  	JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT
  ) ?>;
 
jQuery(document).ready(function($) {

    function normalizeName(str) {
        if (!str) return '';
        return str.toString().toLowerCase().trim().replace(/[\s_+]+/g, '-'); 
    }

    function getMapRegionGroups($mapWrap) {
        return $mapWrap.find('svg > g[name]');
    }

    function getMapRegionFillPaths($region) {
        return $region.find('path').filter(function() {
            const fill = ($(this).attr('fill') || '').toLowerCase();
            return fill === '#6f9c76';
        });
    }

    function clearRegionHighlights($mapWrap) {
        getMapRegionGroups($mapWrap).each(function() {
            getMapRegionFillPaths($(this)).css('fill', '');
        });
    }

    function setRegionHighlight($region, color) {
        getMapRegionFillPaths($region).css('fill', color);
    }

    function getRegionFromClickTarget($el) {
        if ($el.is('[name]')) {
            return $el;
        }
        return $el.closest('g[name]');
    }

    function isRegionHighlighted($region) {
        const $paths = getMapRegionFillPaths($region);
        if (!$paths.length) {
            return false;
        }
        return $paths.first().css('fill') === 'rgb(83, 126, 140)';
    }

    function getRegionCenterSvgCoords(regionEl) {
        const bbox = regionEl.getBBox();
        return {
            x: bbox.x + (bbox.width / 2),
            y: bbox.y + (bbox.height / 2)
        };
    }

    /**
     * Переводит точку из координат SVG (viewBox) в пиксели контейнера .i-map-inner.
     * getBBox() возвращает единицы viewBox, а SVG на экране масштабируется через CSS.
     */
    function svgCoordsToIMapPixels($mapWrap, centerX, centerY) {
        const svg = $mapWrap.find('svg')[0];
        const iMapInner = $mapWrap.find('.i-map-inner')[0];
        if (!svg || !iMapInner || typeof svg.createSVGPoint !== 'function') {
            return null;
        }

        const pt = svg.createSVGPoint();
        pt.x = centerX;
        pt.y = centerY;

        const ctm = svg.getScreenCTM();
        if (!ctm) {
            return null;
        }

        const screenPt = pt.matrixTransform(ctm);
        const mapRect = iMapInner.getBoundingClientRect();

        return {
            x: screenPt.x - mapRect.left,
            y: screenPt.y - mapRect.top
        };
    }

    function applyMarkerPosition($marker, x, y) {
        const markerWidth = $marker.outerWidth() || 53;
        const markerHeight = $marker.outerHeight() || 73;

        $marker.css({
            left: x - (markerWidth / 2) + 'px',
            top: y - markerHeight + 'px',
            display: 'block',
            cursor: 'pointer',
            pointerEvents: 'auto'
        });
    }

    function positionMarkerForRegion($mapWrap, $marker, regionEl) {
        const center = getRegionCenterSvgCoords(regionEl);
        const pixels = svgCoordsToIMapPixels($mapWrap, center.x, center.y);
        if (!pixels) {
            return;
        }
        applyMarkerPosition($marker, pixels.x, pixels.y);
    }

    function repositionMapMarkers($mapWrap) {
        $mapWrap.find('.is-clone').each(function() {
            const regionEl = $(this).data('regionEl');
            if (regionEl) {
                positionMarkerForRegion($mapWrap, $(this), regionEl);
            }
        });
    }

    /**
     * ФУНКЦИЯ СОЗДАНИЯ МАРКЕРА
     * При создании у маркера НЕТ класса active.
     */
    function createMarkerForRegion($mapWrap, $region, regionSlug) {
        const $template = $mapWrap.find('.marker').first();
        if (!$region.length || !$template.length) return;

        const $newMarker = $template.clone()
            .addClass('is-clone')
            .removeClass('marker active') // Явно убираем active при создании
            .attr('data-for-region', regionSlug)
            .data('regionEl', $region[0])
            .appendTo($mapWrap.find('.i-map-inner').first());

        positionMarkerForRegion($mapWrap, $newMarker, $region[0]);
    }

    /**
     * 1. СОБЫТИЕ: КЛИК ПО МЕНЮ ТАБОВ
     */
    $(document).on('click', '.tabs_menu a', function(e) {
        e.preventDefault(); 
        const $this = $(this); 
        const $mapWrap = $this.closest('.map').first();
        const targetTabId = $this.attr('href'); 
        const categoryName = normalizeName($this.data('name')); 

        $mapWrap.find('.tabs_menu a').removeClass('active');
        $this.addClass('active');

        // Скрываем только табы ВНУТРИ карты (не любые элементы .tab на странице)
        const $tabs = $mapWrap.find('.tabs_content_wrapper .tab');
        $tabs.hide().removeClass('show');
        const $currentTab = $mapWrap.find(targetTabId);

        $currentTab.children('div').first().show();
        const $bundle = $currentTab.find('.hidden-posts-bundle').hide().empty();
        
        // Полная очистка: удаляем старые маркеры
        $mapWrap.find('.is-clone').remove();
        clearRegionHighlights($mapWrap);

        let activeRegions = new Set();

        $.each(window.mapData, function(i, post) {
            const isMatch = post.categories.some(function(cat) {
                return normalizeName(cat.name) === categoryName || normalizeName(cat.slug) === categoryName;
            });

            if (isMatch) {
                const $postElement = $(post.html).css('display', 'none');
                if (post.regions && post.regions.length > 0) {
                    $postElement.attr('data-region-slug', normalizeName(post.regions[0]));
                    post.regions.forEach(r => activeRegions.add(normalizeName(r)));
                }
                $bundle.append($postElement);

                if (post.regions) {
                    post.regions.forEach(function(regionSlug) {
                        const normSlug = normalizeName(regionSlug);
                        getMapRegionGroups($mapWrap).each(function() {
                            if (normalizeName($(this).attr('name')) === normSlug) {
                                setRegionHighlight($(this), 'rgb(83, 126, 140)');
                            }
                        });
                    });
                }
            }
        });

        activeRegions.forEach(function(regionSlug) {
            getMapRegionGroups($mapWrap).filter(function() {
                return normalizeName($(this).attr('name')) === regionSlug;
            }).each(function() {
                createMarkerForRegion($mapWrap, $(this), regionSlug);
            });
        });

        $mapWrap.data('activeMapTab', $currentTab);

        if (isMapCompactWidth()) {
            // На мобильной: таб только переключает категорию и маркеры, панель не открываем
            $mapWrap.find('.tabs_content_wrapper').removeClass('open');
            $currentTab.addClass('show').hide().css('display', 'none');
        } else {
            showMapTab($mapWrap, $currentTab);
        }
    });

    function getActiveMapTab($mapWrap) {
        const $storedTab = $mapWrap.data('activeMapTab');
        if ($storedTab && $storedTab.length) {
            return $storedTab;
        }
        return $mapWrap.find('.tabs_content_wrapper .tab.show');
    }

    /**
     * 2. ОБЩАЯ ФУНКЦИЯ ПОКАЗА ПОСТА И ПЕРЕКЛЮЧЕНИЯ ACTIVE
     */
    function showPostForRegion($mapWrap, regionSlug) {
        const $currentTab = getActiveMapTab($mapWrap);
        if (!$currentTab.length) return;

        if (isMapCompactWidth()) {
            openMapPanel($mapWrap, $currentTab);
        }

        // ПЕРЕКЛЮЧЕНИЕ КЛАССА: Сначала снимаем у всех, потом даем одному
        $mapWrap.find('.is-clone').removeClass('active');
        $mapWrap.find('.is-clone[data-for-region="' + regionSlug + '"]').addClass('active');

        const fadeDuration = isMapCompactWidth() ? 150 : 200;
        $currentTab.children('div').first().fadeOut(fadeDuration, function() {
            $currentTab.find('.hidden-posts-bundle').children().hide();
            const $targetPost = $currentTab.find('[data-region-slug="' + regionSlug + '"]');
            if ($targetPost.length > 0) {
                $currentTab.find('.hidden-posts-bundle').show();
                $targetPost.fadeIn(isMapCompactWidth() ? 200 : 300);
            }
        });
    }

    /**
     * 3. ОБРАБОТЧИКИ КЛИКОВ (КАРТА И МАРКЕР)
     */
    $(document).on('click', 'svg g[name] path, svg > g[name]', function() {
        const $region = getRegionFromClickTarget($(this));
        if (!$region.length) {
            return;
        }
        const $mapWrap = $region.closest('.map').first();
        const normRegionName = normalizeName($region.attr('name'));
        if (isRegionHighlighted($region)) {
            showPostForRegion($mapWrap, normRegionName);
        }
    });

    $(document).on('click', '.is-clone', function() {
        const $mapWrap = $(this).closest('.map').first();
        const regionSlug = $(this).attr('data-for-region');
        if (regionSlug) {
            showPostForRegion($mapWrap, regionSlug); // Клик по маркеру делает его активным
        }
    });

    function isMapCompactWidth() {
        return window.matchMedia('(max-width: 1267px)').matches;
    }

    function resetMapTabs($mapWrap) {
        $mapWrap.find('.tabs_menu a').removeClass('active');
        $mapWrap.find('.tabs_content_wrapper').removeClass('open');
        $mapWrap.find('.tabs_content_wrapper .tab').hide().removeClass('show').css('display', 'none');
        $mapWrap.removeData('activeMapTab');
        $mapWrap.find('.is-clone').remove();
        clearRegionHighlights($mapWrap);
    }

    function openMapPanel($mapWrap, $tab) {
        const $wrapper = $mapWrap.find('.tabs_content_wrapper');
        $mapWrap.find('.tabs_content_wrapper .tab').not($tab).removeClass('show').hide();
        $tab.addClass('show').show().css('display', 'block');
        $mapWrap.data('activeMapTab', $tab);
        if ($wrapper[0]) {
            void $wrapper[0].offsetWidth;
        }
        $wrapper.addClass('open');
    }

    function closeMapPanel($mapWrap, callback) {
        const $wrapper = $mapWrap.find('.tabs_content_wrapper');
        $wrapper.removeClass('open');
        setTimeout(function() {
            if (!$wrapper.hasClass('open')) {
                if (isMapCompactWidth()) {
                    // На мобилке категория остаётся активной — только прячем контент
                    const $activeTab = getActiveMapTab($mapWrap);
                    if ($activeTab.length) {
                        $activeTab.hide().css('display', 'none');
                    }
                } else {
                    $mapWrap.find('.tabs_content_wrapper .tab').removeClass('show').hide().css('display', 'none');
                    $mapWrap.removeData('activeMapTab');
                }
                if (typeof callback === 'function') {
                    callback();
                }
            }
        }, 350);
    }

    function showMapTab($mapWrap, $tab) {
        if (isMapCompactWidth()) {
            openMapPanel($mapWrap, $tab);
        } else {
            $tab.fadeIn(300).addClass('show');
        }
    }

    $(document).on('click', '.map-panel-close', function(e) {
        e.preventDefault();
        const $mapWrap = $(this).closest('.map').first();
        closeMapPanel($mapWrap, function() {
            if (!isMapCompactWidth()) {
                $mapWrap.find('.tabs_menu a').removeClass('active');
                $mapWrap.find('.is-clone').remove();
                clearRegionHighlights($mapWrap);
                $mapWrap.removeData('activeMapTab');
            }
        });
    });

    // Инициализируем только активные табы ВНУТРИ каждой карты
    $('.map').each(function() {
        const $mapWrap = $(this);
        if (isMapCompactWidth()) {
            resetMapTabs($mapWrap);
        } else {
            $mapWrap.find('.tabs_menu a').first().trigger('click');
        }
    });

    $(window).on('resize scroll', function() {
        $('.map').each(function() {
            const $mapWrap = $(this);

            if ($mapWrap.find('.is-clone').length) {
                repositionMapMarkers($mapWrap);
            }
        });
    });
});

</script>


