    <?php 
    // Заходим в повторитель 'tabs' из Option Page
    if ( have_rows( 'tabs', 'option' ) ) : 
        $count = 1; // Начинаем с единицы для #tab1, #tab2...
        
        while ( have_rows( 'tabs', 'option' ) ) : the_row();
            
            // Берем текст из твоего текстового поля 'tab'
            $tab_text = get_sub_field( 'tab' ); 
            $anchor =  get_sub_field( 'anchor' ); 
            if ( $tab_text ) : ?>
                <li>
                    <a data-name="<?php echo esc_html( $anchor ); ?>" href="#tab<?php echo $count; ?>">
                        <?php echo esc_html( $tab_text ); ?>
                    </a>
                </li>
                <?php 
                $count++; // Увеличиваем на 1 для следующей итерации
            endif;
            
        endwhile; 
    endif; 
    ?>
