<div class="tabs_content_wrapper">
    <button type="button" class="map-panel-close" aria-label="<?php echo esc_attr__( 'Close', 'traveliz' ); ?>">&times;</button>
    <?php 
    if ( have_rows( 'content_tabs', 'option' ) ) : 
        $count = 1;
        while ( have_rows( 'content_tabs', 'option' ) ) : the_row();
            
            $title = get_sub_field('title_content');
            $text  = get_sub_field('text_content');
            $img   = get_sub_field('img_content'); 
            $btn_text = get_sub_field('button_text');
            $btn_link = get_sub_field('buttom_link');
            ?>
            
            <div class="tab" id="tab<?php echo $count; ?>" style="display:none;">
                
                <div class="static-post">
                    <h3><?php echo esc_html($title); ?></h3>
                    
                    <?php if ( $img ) : ?>
                        <img src="<?php echo is_array($img) ? $img['url'] : $img; ?>" alt="">
                    <?php endif; ?>

                    <?php if ( $btn_text && $btn_link ) : ?>
                        <a href="<?php echo esc_url($btn_link); ?>"><?php echo esc_html($btn_text); ?></a>
                    <?php endif; ?>
                    <p><?php echo nl2br(esc_html($text)); ?></p>
                </div>
                
                <div class="hidden-posts-bundle" style="display: none;">
                 </div>

            </div>
        <?php 
        $count++; 
        endwhile; 
    endif; ?>
</div>
			</div>
		</div>
	</div>
</div>
</section>